 "content": "from collections import Counter


def transform(grid):
    """Copy the non-background design in the occupied panel into each panel."""
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Full-width / full-height uniform separator lines partition the canvas.
    row_cuts = [r for r, row in enumerate(grid)
                if len(set(row)) == 1 and row[0] != bg]
    col_cuts = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]
    row_ranges = []
    start = 0
    for cut in row_cuts:
        if start < cut:
            row_ranges.append((start, cut))
        start = cut + 1
    if start < h:
        row_ranges.append((start, h))
    col_ranges = []
    start = 0
    for cut in col_cuts:
        if start < cut:
            col_ranges.append((start, cut))
        start = cut + 1
    if start < w:
        col_ranges.append((start, w))

    panels = []
    for r0, r1 in row_ranges:
        for c0, c1 in col_ranges:
            count = sum(grid[r][c] != bg for r in range(r0, r1) for c in range(c0, c1))
            panels.append((count, r0, r1, c0, c1))
    if not panels:
        return [row[:] for row in grid]
    _, sr0, sr1, sc0, sc1 = max(panels)
    pattern = [(r - sr0, c - sc0, grid[r][c])
               for r in range(sr0, sr1) for c in range(sc0, sc1)
               if grid[r][c] != bg]
    out = [row[:] for row in grid]
    for _, r0, r1, c0, c1 in panels:
        if (r1 - r0, c1 - c0) != (sr1 - sr0, sc1 - sc0):
            continue
        for dr, dc, color in pattern:
            out[r0 + dr][c0 + dc] = color
    return out


if __name__ == "__main__":
    pass
